<?php
require_once __DIR__.'/includes/functions.php';require_login();require_once __DIR__.'/config/database.php';$pageTitle='Categories';
if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();$action=$_POST['action']??'';if($action==='save'){$id=(int)($_POST['id']??0);$name=trim($_POST['name']??'');$desc=trim($_POST['description']??'');if($name===''){flash('danger','Category name is required.');redirect('categories.php');}try{if($id){$q=$pdo->prepare('UPDATE categories SET name=?,description=? WHERE id=?');$q->execute([$name,$desc,$id]);flash('success','Category updated.');}else{$q=$pdo->prepare('INSERT INTO categories(name,description) VALUES(?,?)');$q->execute([$name,$desc]);flash('success','Category added.');}}catch(PDOException $e){flash('danger','Category name already exists or could not be saved.');}redirect('categories.php');}if($action==='delete'){try{$q=$pdo->prepare('DELETE FROM categories WHERE id=?');$q->execute([(int)$_POST['id']]);flash('success','Category deleted. Products in this category will remain without a category.');}catch(PDOException $e){flash('danger','Could not delete category.');}redirect('categories.php');}}
$edit=null;if(isset($_GET['edit'])){$q=$pdo->prepare('SELECT * FROM categories WHERE id=?');$q->execute([(int)$_GET['edit']]);$edit=$q->fetch();}
$rows=$pdo->query('SELECT c.*,COUNT(p.id) AS product_count FROM categories c LEFT JOIN products p ON p.category_id=c.id GROUP BY c.id ORDER BY c.name')->fetchAll();require __DIR__.'/includes/header.php';
?>
<div class="row"><div class="col-md-4"><div class="card card-primary card-outline"><div class="card-header"><h3 class="card-title"><?= $edit?'Edit Category':'Add Category' ?></h3></div><form method="post"><div class="card-body"><input type="hidden" name="csrf_token" value="<?=e(csrf_token())?>"><input type="hidden" name="action" value="save"><input type="hidden" name="id" value="<?= (int)($edit['id']??0) ?>"><div class="form-group"><label class="required">Category name</label><input class="form-control" name="name" maxlength="100" required value="<?=e($edit['name']??'')?>"></div><div class="form-group"><label>Description</label><textarea class="form-control" name="description" rows="3"><?=e($edit['description']??'')?></textarea></div></div><div class="card-footer"><button class="btn btn-primary">Save Category</button><?php if($edit):?> <a class="btn btn-default" href="categories.php">Cancel</a><?php endif;?></div></form></div></div><div class="col-md-8"><div class="card"><div class="card-header"><h3 class="card-title">All Categories</h3></div><div class="card-body table-responsive p-0"><table class="table table-hover"><thead><tr><th>Name</th><th>Description</th><th>Products</th><th>Action</th></tr></thead><tbody><?php if(!$rows):?><tr><td colspan="4" class="empty-state">No categories yet.</td></tr><?php else:foreach($rows as $r):?><tr><td><?=e($r['name'])?></td><td><?=e($r['description'])?></td><td><span class="badge badge-info"><?=$r['product_count']?></span></td><td class="text-nowrap"><a class="btn btn-xs btn-info" href="categories.php?edit=<?=(int)$r['id']?>"><i class="fas fa-edit"></i></a> <form method="post" class="d-inline"><input type="hidden" name="csrf_token" value="<?=e(csrf_token())?>"><input type="hidden" name="action" value="delete"><input type="hidden" name="id" value="<?=(int)$r['id']?>"><button class="btn btn-xs btn-danger" data-confirm="Delete this category?" <?= $r['product_count']?'title="Products will become uncategorized"':''?>><i class="fas fa-trash"></i></button></form></td></tr><?php endforeach;endif;?></tbody></table></div></div></div></div>
<?php require __DIR__.'/includes/footer.php';?>
